import { buttonVariants, type ButtonVariants } from "../button/variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"button">, ButtonVariants {}

<const/{ variant, size = "icon-xs", class: className, content, ...rest }=input/>

<button
  data-slot="attachment-action"
  class=cn(buttonVariants({ variant: variant ?? "ghost", size }), "", className)
  ...rest
>
  <${content}/>
</button>

import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {}

<const/{ class: className, content, ...rest }=input/>

<div
  data-slot="attachment-actions"
  class=cn("group-data-[orientation=vertical]/attachment:absolute group-data-[orientation=vertical]/attachment:top-3 group-data-[orientation=vertical]/attachment:right-3 relative z-20 group-data-[orientation=vertical]/attachment:gap-1 flex shrink-0 items-center", className)
  ...rest
>
  <${content}/>
</div>

import { attachmentVariants, type AttachmentVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, AttachmentVariants {
  state?: "idle" | "uploading" | "processing" | "error" | "done";
}

<const/{
  state = "done",
  size = "default",
  orientation = "horizontal",
  class: className,
  content,
  ...rest
}=input/>

<div
  data-slot="attachment"
  data-state=state
  data-size=size
  data-orientation=orientation
  class=cn(attachmentVariants({ size, orientation }), className)
  ...rest
>
  <${content}/>
</div>

